import { DisplayFlexCCC } from '../../../../../../../commonStyle/index.style'
import PdfContainer from '../../../../../../../components/PdfContainer'
import ZoomImg from '../../../../../../../components/zoomImg'
import { PrintMultipleImageWrapper } from './index.style'

function PrintMultipleImage ({ data }) {
  const imagePayload = Array.isArray(data) ? data : typeof data === 'object' ? Object.values(data) : [data]

  return (
    imagePayload.length <= 1 ? (
      <PdfContainer url={imagePayload[0]} />
    ) : (
      <PrintMultipleImageWrapper>
        {
          imagePayload?.map((item, index) => (
            <ZoomImg
              key={index}
              src={item}
              imgContainer={
                <DisplayFlexCCC className='container'>
                  <img src={item} alt='Certificate' />
                </DisplayFlexCCC>
              }
            />
          ))
        }
      </PrintMultipleImageWrapper>
    ))
}

export default PrintMultipleImage
