import { useCallback, useMemo, useState, useEffect, useRef } from 'react'
import { Container, CustomText } from '../../../../../../components'
import CollapsibleCard from '../../../../../../components/CollapsibleCard'
import InfoHeader from '../../../../../../components/InfoHeader'
import StepsHeader from '../../../../../../components/StepsHeader'
import TitleEditHeading from '../../../../../../components/TitleEditHeading'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import {
  getFromLocalStorageData,
  setToLocalStorage,
} from '../../../../../../helpers/localstorage'
import { LANG_STRINGS, ERROR_LANG } from '../../../../../../lang'
import BottomBtn from '../../../../../../components/BottomBtn'
import {
  AddOnsStyleWrapper,
  InstantApprovalStyleWrapper,
  OfflinePolicyReviewFormStyle,
  PolicyInfoStyle,
} from './index.style'
import { SEND_GOLD_ICON } from '../../../../../../images'
import { useHistory } from 'react-router'
import {
  useCreateOfflineQuote,
  useGetOfflineQuoteDetail,
  useValidateChassisNumber,
} from '../../../state/hooks/usePolicyState'
import {
  resetError,
  updateLoader,
  useErrorContextValue,
  useLoaderContextValue,
} from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import {
  ADDITIONAL_INFORMATION_REQUIRED,
  DOCUMENT_INCOMPLETE,
  SUBMITTED,
  OFFLINE_POLICY_PURCHASE_TYPE,
  CAR_PROTECTION,
} from '../../../../../../constants/pkgCode'
import { InstantTermsStyle } from '../../../../../CommonContainer/OfflinePolicyContainer/index.style'
import { Row } from '../../../../../../commonStyle/index.style'
import CustomCheckbox from '../../../../../../components/CustomCheckbox'
import BottomActionSheet from '../../../../../../components/BottomActionSheet'
import {
  CONTAINER_HEADING,
  OFFLINE_POLICY_PURCHASE_TYPE_OTHER,
  OFFLINE_MANUAL_FORM_DATA,
} from '../../OfflineProductManualOrder/constant'
import { getAddonsMapFromCategory } from '../../../../../../helpers/getPackageBody'
import PrintPolicyData from '../../../../../CommonContainer/OfflinePolicyContainer/components/PrintPolicyData'
import { modifyKey } from '../../OfflinePolicyForm/constant'
import PdfContainer from '../../../../../../components/PdfContainer'
import OfflinePolicyAddonsData from '../../../../../CommonContainer/OfflinePolicyContainer/components/OfflineAddonsData'
import VehicleModificationData from '../../../../../CommonContainer/OfflinePolicyContainer/components/VehicleModificationData'
import PrintMultipleImage from '../components/PrintMultipleImage'
import OfflinePolicyContainer from '../../../../../CommonContainer/OfflinePolicyContainer'
import { formatMoney, getIDRCurrency } from '../../../../../../helpers/utility'
import moment from 'moment'
import RenderLossRecordDetails from '../components/RenderLossRecordDetails'

function OfflinePolicyReviewFormContainer(props) {
  const urlParams = useMemo(() => props?.match?.params || {}, [props])
  // const productName = useMemo(() => props?.location?.state?.name, [props])
  const validateChassisRef = useRef({
    apiCount: 3,
    clearChassisTimeOut: '',
  })
  const [isChassisValid, setChassisValid] = useState(true)
  const history = useHistory()
  const that = useRef({})
  const { productCode, step } = props?.match?.params
  const [{ createOfflineQuoteData }, createOfflineQuoteRequest] =
    useCreateOfflineQuote()
  const [{ offlineQuoteDetailData = {} }, offlineQuoteDetailReq] =
    useGetOfflineQuoteDetail()
  const [
    { CREATE_OFFLINE_QUOTE_LOADER, OFFLINE_QUOTE_DETAIL_LOADER },
    dispatchLoader,
  ] = useLoaderContextValue()
  const [
    {
      createOfflineQuoteStatus,
      offlineQuoteDetailStatus,
      validateChassisNoStatus,
    },
    dispatchError,
  ] = useErrorContextValue()
  const [{ validateChassisNoData = {} }, validateChassisNoReq] =
    useValidateChassisNumber()
  const [pageConfig, setPageConfig] = useState(() => {
    let config = {
      isOfflineOrderDetails: false,
    }
    if (urlParams.policyId) {
      config = {
        ...config,
        title: LANG_STRINGS.orderDetails,
        quoteId: urlParams.policyId,
        isOfflineOrderDetails: true,
      }
    }
    return config
  })

  const [getLocalOfflineFormData, setLocalOfflineFormData] = useState({
    ...(getFromLocalStorageData(OFFLINE_MANUAL_FORM_DATA) || {}),
    protection_case: 'manual-order',
  })

  const isCarProtection = useMemo(
    () => getLocalOfflineFormData.product_key === CAR_PROTECTION,
    [getLocalOfflineFormData]
  )

  const validateChassis = useCallback(
    (formData) => {
      const {
        chasis_number: chasisNumber,
        coverage_period_start: startDate,
        code,
      } = formData
      if (chasisNumber) {
        validateChassisNoReq({
          body: {
            code,
            pre_validate_data: {
              chasis_number: {
                chasis_number: chasisNumber,
                start_date: startDate,
              },
            },
          },
        })
      }
    },
    [validateChassisNoReq]
  )

  useEffect(() => {
    // validate chassis number
    if (validateChassisNoStatus === 'success') {
      // check is data is ok if not then show error
      if (!validateChassisNoData.success) {
        setChassisValid(false)
      } else if (validateChassisNoData.is_request_pending) {
        validateChassisRef.current.clearChassisTimeOut = setTimeout(() => {
          validateChassis(getLocalOfflineFormData)
        }, 20000)
      } else {
        setChassisValid(true)
      }
      dispatchError(
        resetError({
          validateChassisNoStatus: '',
        })
      )
    } else if (validateChassisNoStatus) {
      if (!validateChassisRef.current.apiCount) {
        ShowSnackbar.error({
          visible: true,
          text: validateChassisNoStatus,
        })
      } else {
        validateChassisRef.current.apiCount -= 1
        validateChassis(getLocalOfflineFormData)
      }
      dispatchError(
        resetError({
          validateChassisNoStatus: '',
        })
      )
    }
  }, [
    validateChassis,
    dispatchError,
    validateChassisNoStatus,
    validateChassisNoData,
    getLocalOfflineFormData,
  ])

  const disabledBtn = useMemo(() => {
    return [
      SUBMITTED,
      DOCUMENT_INCOMPLETE,
      ADDITIONAL_INFORMATION_REQUIRED,
    ].includes(offlineQuoteDetailData?.status)
  }, [offlineQuoteDetailData?.status])

  const [showInstantTerms, setInstantTerms] = useState(false)
  const [checkedInstantApproval, setCheckedInstantApproval] = useState(
    pageConfig.isOfflineOrderDetails
      ? getLocalOfflineFormData.instant_approve
      : getLocalOfflineFormData.prov_maps?.length === 1
  )

  useEffect(() => {
    if (urlParams.policyId && OFFLINE_QUOTE_DETAIL_LOADER === undefined) {
      offlineQuoteDetailReq({
        quoteId: urlParams.policyId,
      })
    }
  }, [urlParams.policyId, OFFLINE_QUOTE_DETAIL_LOADER, offlineQuoteDetailReq])

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          CREATE_OFFLINE_QUOTE_LOADER: undefined,
          OFFLINE_QUOTE_DETAIL_LOADER: undefined,
        })
      )
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (createOfflineQuoteStatus === 'success') {
      history.push(`/offline/success/${createOfflineQuoteData.id}`)
      dispatchError(
        resetError({
          createOfflineQuoteStatus: undefined,
        })
      )
    } else if (createOfflineQuoteStatus) {
      ShowSnackbar.error({
        visible: true,
        text: createOfflineQuoteStatus,
      })
      dispatchError(
        resetError({
          createOfflineQuoteStatus: undefined,
        })
      )
    }

    if (offlineQuoteDetailStatus === 'success') {
      setLocalOfflineFormData(offlineQuoteDetailData.policy_details)
      validateChassis(offlineQuoteDetailData.policy_details)
      setPageConfig((pageConfig) => ({
        ...pageConfig,
        showEditQuoteData: [DOCUMENT_INCOMPLETE].includes(
          offlineQuoteDetailData.status
        ),
      }))
      setCheckedInstantApproval(offlineQuoteDetailData.instant_approve)
      dispatchError(
        resetError({
          offlineQuoteDetailStatus: undefined,
        })
      )
    }
  }, [
    createOfflineQuoteStatus,
    dispatchError,
    offlineQuoteDetailData,
    history,
    createOfflineQuoteData,
    offlineQuoteDetailStatus,
    validateChassis,
  ])

  const handleEditClick = useCallback(
    (step) => {
      if (pageConfig.quoteId) {
        setToLocalStorage(OFFLINE_MANUAL_FORM_DATA, getLocalOfflineFormData)
      }
      history.push({
        pathname: `/${productCode || getLocalOfflineFormData?.product_key}/form/${pageConfig.quoteId}/${step}/edit`,
        state: {
          package_type: getLocalOfflineFormData?.package_type,
          name:
            getLocalOfflineFormData?.product_key === 'car-protection'
              ? 'Mobil'
              : 'Properti',
        },
      })
    },
    [productCode, history, getLocalOfflineFormData, pageConfig.quoteId]
  )

  const handleCheckbox = useCallback(() => {
    setCheckedInstantApproval((checked) => {
      that.current.instantChecked = !checked
      return !checked
    })
  }, [])

  const handleShowTermsToggle = useCallback(() => {
    setInstantTerms((prevShow) => !prevShow)
  }, [])

  const renderInstantApproval = () => {
    return (
      <InstantApprovalStyleWrapper>
        <Row align="center" justify="space-between" className="pad-12">
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size="14px"
            weight={800}
          >
            {LANG_STRINGS.partnerApproval}
          </CustomText>
          <CustomCheckbox
            onChange={handleCheckbox}
            name="instant_approval"
            disabled={pageConfig.isOfflineOrderDetails}
            isChecked={checkedInstantApproval}
            color={AgentColorPallette.black}
          />
        </Row>
        <CustomText
          color={AgentColorPallette.blackGrey}
          className="instant-terms-body"
        >
          {LANG_STRINGS.iAgreeWith}
          <span className="offline-terms" onClick={handleShowTermsToggle}>
            &nbsp;{LANG_STRINGS.termsConditions}
          </span>
        </CustomText>
      </InstantApprovalStyleWrapper>
    )
  }

  const getProviderNames = (providers = [], isCoinsurance = false) => {
    const providerNames = providers.map((provider) =>
      isCoinsurance ? provider.provider_data.name : provider.name
    )
    return providerNames.join(', ')
  }

  const formattedData = useCallback(
    (key, type) => {
      const keyData = modifyKey({ current: getLocalOfflineFormData }, key)
      if (['uploadFileButton']?.includes(type)) {
        return keyData ? <PdfContainer url={keyData} /> : '-'
      } else if (type === 'uploadImage') {
        return keyData ? <PrintMultipleImage data={keyData} /> : '-'
      } else if (key === 'prov_maps') {
        return getProviderNames(
          Object.values(
            getLocalOfflineFormData?.providerData ||
              getLocalOfflineFormData?.prov_maps
          ),
          getLocalOfflineFormData?.isCoinsurance
        )
      } else if (['auto_calculate', 'amount'].includes(type)) {
        const amount = keyData
        return formatMoney(
          amount,
          0,
          getLocalOfflineFormData?.currency_symbol,
          getLocalOfflineFormData?.currency_symbol === 'Rp' ? ',' : '.',
          getLocalOfflineFormData?.currency_symbol === 'Rp' ? '.' : ','
        )
      } else if (type === 'date') {
        return moment(getLocalOfflineFormData[key]).format('DD MMM YYYY')
      } else if (type === 'timepicker') {
        return moment(getLocalOfflineFormData[key]).format('HH:mm')
      } else if (type === 'lossRecord') {
        return (
          <RenderLossRecordDetails
            data={getLocalOfflineFormData?.loss_record_doc}
          />
        )
      } else if (key === 'survey_report') {
        const filesName = getLocalOfflineFormData[key]?.map((file) =>
          file.slice(file.lastIndexOf('/') + 1)
        )
        return filesName.join(', ')
      }
      return typeof keyData !== 'object' ? keyData : '-'
    },
    [getLocalOfflineFormData]
  )

  const mapHardCopyData = (getLocalOfflineFormData) => {
    return {
      hard_copy_required: getLocalOfflineFormData.hard_copy_required,
      insurance_details: {
        hard_copy_address: getLocalOfflineFormData.hard_copy_address,
        hard_copy_details: {
          recipient_name: getLocalOfflineFormData.hard_copy_recipient,
          hard_copy_recipient_mobile:
            getLocalOfflineFormData.hard_copy_recipient_mobile,
        },
      },
    }
  }

  const handleInstantChecked = useCallback((checked) => {
    that.current.instantChecked = checked
    setCheckedInstantApproval(checked)
  }, [])

  const renderSection = useCallback(() => {
    if (getLocalOfflineFormData?.reviewFormData) {
      return Object.values(getLocalOfflineFormData?.reviewFormData || {})?.map(
        (section, index) => {
          return (
            <div className="form-container" key={index}>
              <div className="review-form">
                <TitleEditHeading
                  title={section.page_heading}
                  showEditBtn={pageConfig.showEditQuoteData}
                  onEditClick={() => {
                    pageConfig.showEditQuoteData && handleEditClick(index + 1)
                  }}
                />
                {section?.section?.map((item, index) => {
                  return item.section_data[0]?.displayLabel ===
                    LANG_STRINGS.printPolicy ? (
                    <AddOnsStyleWrapper>
                      <PrintPolicyData
                        policy={mapHardCopyData(getLocalOfflineFormData)}
                      />
                    </AddOnsStyleWrapper>
                  ) : item.section_data[0]?.displayLabel ===
                    LANG_STRINGS.packageAddons ? (
                    <AddOnsStyleWrapper>
                      <OfflinePolicyAddonsData
                        policyData={getLocalOfflineFormData}
                      />
                    </AddOnsStyleWrapper>
                  ) : item.section_data[0]?.displayLabel ===
                    LANG_STRINGS.vehicleModification ? (
                    <VehicleModificationData
                      policyData={getLocalOfflineFormData}
                      hidePhotos
                      {...props}
                    />
                  ) : (
                    <CollapsibleCard
                      title={item.section_heading}
                      isOpen
                      key={index}
                    >
                      {item?.section_data?.map((sectionData, index) => (
                        <PolicyInfoStyle
                          isBorder={index + 1 !== item.section_data.length}
                          align="center"
                          display="block"
                          justify="space-between"
                          onClick={
                            sectionData.onClick ? sectionData.onClick : () => {}
                          }
                          key={index}
                          bgColor={sectionData.bgColor}
                        >
                          <CustomText color={AgentColorPallette.fontDarkerGrey}>
                            {sectionData?.displayLabel}
                          </CustomText>
                          <CustomText
                            className="break-word-newline"
                            color={AgentColorPallette.darkCharcoal}
                            weight={800}
                          >
                            {formattedData(
                              sectionData.name,
                              sectionData.type
                            ) || '-'}
                          </CustomText>
                        </PolicyInfoStyle>
                      ))}
                    </CollapsibleCard>
                  )
                })}
              </div>
              <div className="separator" />
            </div>
          )
        }
      )
    }

    return (
      <OfflinePolicyContainer
        history={history}
        pageConfig={pageConfig}
        policyData={getLocalOfflineFormData}
        onInstantChecked={handleInstantChecked}
        isHideInstantChecked
        quoteData={offlineQuoteDetailData}
      />
    )
  }, [
    formattedData,
    getLocalOfflineFormData,
    handleEditClick,
    pageConfig,
    handleInstantChecked,
    offlineQuoteDetailData,
    history,
    props,
  ])

  const handlePurchaseType = useCallback(
    (code) => {
      return isCarProtection
        ? OFFLINE_POLICY_PURCHASE_TYPE[code]
        : OFFLINE_POLICY_PURCHASE_TYPE_OTHER[code]
    },
    [isCarProtection]
  )

  const handleSubmit = useCallback(() => {
    const code = getLocalOfflineFormData?.protection_type?.code
    const body = {
      ...getLocalOfflineFormData,
      ...getAddonsMapFromCategory(getLocalOfflineFormData.addons),
      instant_approve: checkedInstantApproval,
      purchase_type: handlePurchaseType(code),
    }

    if (
      getLocalOfflineFormData.accessories &&
      getLocalOfflineFormData?.currency_label !== 'IDR'
    ) {
      const accessories = getLocalOfflineFormData.accessories?.map((el) => {
        el.sum_insured = getIDRCurrency(
          el.sum_insured,
          getLocalOfflineFormData?.exchange_rate
        )
        return el
      })
      body.accessories = accessories
      body.totalSumInsured = getIDRCurrency(
        getLocalOfflineFormData?.totalSumInsured,
        getLocalOfflineFormData?.exchange_rate
      )
    }

    if (getLocalOfflineFormData.vehicle_sum_insured) {
      if (getLocalOfflineFormData?.currency_label !== 'IDR') {
        const sumInsured = getLocalOfflineFormData.vehicle_sum_insured
        body.vehicle_sum_insured = getIDRCurrency(
          sumInsured,
          getLocalOfflineFormData?.exchange_rate
        )
      }
      delete body.vehiclePrice
    }

    if (getLocalOfflineFormData.providerData) {
      body.prov_maps = Object.values(getLocalOfflineFormData.providerData)
      delete body.providerData
    }
    body.additional_sum_insured = 0
    body.type = 'NORMAL' // this is for normal o2o policy
    // force set model & variant
    body.model = getLocalOfflineFormData.model_code
    body.variant = getLocalOfflineFormData.variant_name

    createOfflineQuoteRequest({
      body,
    })
  }, [
    getLocalOfflineFormData,
    createOfflineQuoteRequest,
    checkedInstantApproval,
    handlePurchaseType,
  ])

  const handleToAdditionalInfo = useCallback(() => {
    history.push(`/offline/quotes/additional/info/${offlineQuoteDetailData.id}`)
  }, [history, offlineQuoteDetailData.id])

  const renderInfoSection = useCallback(() => {
    if (
      pageConfig.isOfflineOrderDetails &&
      !offlineQuoteDetailData.remarks &&
      offlineQuoteDetailData.status !== ADDITIONAL_INFORMATION_REQUIRED
    ) {
      return null
    }
    let info = pageConfig.isOfflineOrderDetails
      ? offlineQuoteDetailData.remarks
      : LANG_STRINGS.reviewYourDetailsBeforeSubmit
    if (offlineQuoteDetailData.status === ADDITIONAL_INFORMATION_REQUIRED) {
      info = LANG_STRINGS.someAdditionalInfoRequired
    }
    return (
      <>
        <InfoHeader
          info={info}
          bgColor={
            offlineQuoteDetailData.remarks
              ? AgentColorPallette.maroonRed
              : AgentColorPallette.black
          }
        />
        {offlineQuoteDetailData.status === ADDITIONAL_INFORMATION_REQUIRED && (
          <Row
            justify="space-between"
            align="center"
            className="additional-info-btn"
            onClick={handleToAdditionalInfo}
          >
            <CustomText
              size="14px"
              color={AgentColorPallette.black}
              weight={700}
            >
              {LANG_STRINGS.additionalInfo}
            </CustomText>
            <CustomText color={AgentColorPallette.fontSecondary} weight={700}>
              <i className="fas fa-angle-right" />
            </CustomText>
          </Row>
        )}
      </>
    )
  }, [pageConfig, offlineQuoteDetailData, handleToAdditionalInfo])

  return (
    <OfflinePolicyReviewFormStyle>
      <Container
        title={
          pageConfig.title ||
          `${CONTAINER_HEADING[productCode]}: ${LANG_STRINGS.manualOrder}`
        }
        hideBottomTabs
        displayBackButton
        loader={CREATE_OFFLINE_QUOTE_LOADER}
      >
        {!isChassisValid && pageConfig.isOfflineOrderDetails && (
          <div className="validation-error">
            <CustomText size="12px" weight={700}>
              {ERROR_LANG.vehicleAlreadyHasAnActivePolicy}
            </CustomText>
          </div>
        )}
        {!pageConfig.isOfflineOrderDetails && (
          <StepsHeader
            leftText={LANG_STRINGS.overview}
            current={step}
            totalSteps={step}
          />
        )}
        {renderInfoSection()}
        {renderSection()}
        {renderInstantApproval()}
        <BottomActionSheet
          show={showInstantTerms}
          onCloseSheet={handleShowTermsToggle}
        >
          <InstantTermsStyle>
            <Row justify="space-between" className="instant-terms-header">
              <CustomText
                size="13px"
                weight="800"
                className="item-padding"
                color={AgentColorPallette.fontDarkerGrey}
              >
                {LANG_STRINGS.termsConditions}
              </CustomText>
              <CustomText
                size="15px"
                weight="800"
                className="item-padding"
                color={AgentColorPallette.fontDarkerGrey}
                onClick={handleShowTermsToggle}
              >
                X
              </CustomText>
            </Row>
            <CustomText
              size="1em"
              color={AgentColorPallette.blackGrey}
              className="bg-white"
              padLeft="12px"
              padRight="12px"
              padBottom="12px"
              top="12px"
            >
              {LANG_STRINGS.byCheckingThisYouAcceptTheOffers}
            </CustomText>
          </InstantTermsStyle>
        </BottomActionSheet>
        {!pageConfig.isOfflineOrderDetails && (
          <div className="submit-button-wrapper">
            <BottomBtn
              title={LANG_STRINGS.submitCalculation}
              icon={SEND_GOLD_ICON}
              onClick={handleSubmit}
              disabled={disabledBtn}
            />
          </div>
        )}
        <ShowSnackbar />
      </Container>
    </OfflinePolicyReviewFormStyle>
  )
}

export default OfflinePolicyReviewFormContainer
