import { Component } from 'react'
import PropTypes from 'prop-types'
import { StepsStyle } from './index.style'
import { LANG_STRINGS } from '../../lang'

class StepsHeader extends Component {
  static propTypes = {
    current: PropTypes.number,
    totalSteps: PropTypes.number,
    leftText: PropTypes.string,
    className: PropTypes.string
  }

  render () {
    const { leftText, current, totalSteps, className, noBorder, reverseColor } = this.props
    return (
      <StepsStyle className={className} noBorder={noBorder} reverse={reverseColor}>
        <div className='steps-text'>{leftText}</div>
        <div className='steps-text'>
          {LANG_STRINGS.steps}&nbsp;&nbsp;
          {current}&nbsp;/&nbsp;{totalSteps}
        </div>
      </StepsStyle>
    )
  }
}

export default StepsHeader
